import re
from datetime import datetime, timedelta, timezone
from decimal import Decimal
from mcp.server.fastmcp import FastMCP
from custody_client import CustodyClient
mcp = FastMCP('wallet-ops')
custody = CustodyClient.from_env()
_ADDRESS_RE = re.compile('^0x[a-fA-F0-9]{40}$')
_MAX_SPEND_USD = Decimal('10000')
_MAX_GAS_ETH = Decimal('0.05')


def _revoke_existing_session_keys(wallet_id: str, session_address: str) -> list:
    # Revoke any previously granted keys for this signer so only the new grant is active
    revoked = []
    for key in custody.session_keys.list(wallet_id=wallet_id):
        if key.get('signer_address', '').lower() == session_address.lower() and not key.get('revoked'):
            custody.session_keys.revoke(key['id'])
            revoked.append(key['id'])
    return revoked


@mcp.tool()
def grant_funded_session_key(wallet_id: str, session_address: str, spend_limit_usd: float, ttl_hours: int, gas_amount_eth: float) -> dict:
    if not wallet_id or not wallet_id.strip():
        return {'ok': False, 'error': 'wallet_id is required'}
    if not _ADDRESS_RE.match(session_address or ''):
        return {'ok': False, 'error': 'session_address must be a 0x-prefixed 20-byte hex address'}
    limit = Decimal(str(spend_limit_usd))
    if limit <= 0 or limit > _MAX_SPEND_USD:
        return {'ok': False, 'error': f'spend_limit_usd must be between 0 and {_MAX_SPEND_USD}'}
    if ttl_hours < 1 or ttl_hours > 168:
        return {'ok': False, 'error': 'ttl_hours must be between 1 and 168'}
    gas = Decimal(str(gas_amount_eth))
    if gas <= 0 or gas > _MAX_GAS_ETH:
        return {'ok': False, 'error': f'gas_amount_eth must be between 0 and {_MAX_GAS_ETH}'}
    wallet = custody.wallets.get(wallet_id)
    if wallet is None:
        return {'ok': False, 'error': f'wallet {wallet_id} not found'}
    if wallet.get('frozen'):
        return {'ok': False, 'error': 'wallet is frozen'}
    if session_address.lower() == wallet['address'].lower():
        return {'ok': False, 'error': "session_address cannot be the wallet's own address"}
    if Decimal(wallet['balances'].get('ETH', '0')) < gas:
        return {'ok': False, 'error': 'insufficient ETH balance for gas funding'}
    expires_at = datetime.now(timezone.utc) + timedelta(hours=ttl_hours)
    revoked_ids = _revoke_existing_session_keys(wallet_id, session_address)
    grant = custody.session_keys.grant(wallet_id=wallet_id, signer_address=session_address, spend_limit_usd=str(limit), expires_at=expires_at.isoformat())
    transfer = custody.transfers.send(wallet_id=wallet_id, asset='ETH', amount=str(gas), to_address=session_address, memo=f"gas for session key {grant['id']}")
    return {'ok': True, 'session_key_id': grant['id'], 'expires_at': expires_at.isoformat(), 'spend_limit_usd': str(limit), 'gas_tx_hash': transfer['tx_hash'], 'revoked_session_key_ids': revoked_ids}
